// Every colour in strip order, for the conformance test and any future
// palette texture upload.
inline const Color* rampByIndex(int ramp, int& stepsOut) {
  switch (ramp) {
    case 0: stepsOut = neutralSteps; return neutral;
    case 1: stepsOut = greySteps; return grey;
    case 2: stepsOut = brownSteps; return brown;
    case 3: stepsOut = yellowSteps; return yellow;
    case 4: stepsOut = greenSteps; return green;
    case 5: stepsOut = blueSteps; return blue;
    case 6: stepsOut = accentSteps; return accent;
    default: stepsOut = 0; return nullptr;
  }
}
